package com.script.comminutioncraft.client;

import java.util.Locale;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.inventory.AbstractContainerMenu;

/**
 * Dark Chassis GUI shared by every machine. Sheets are 256x256, generated by tools/gui_dark_chassis.py:
 * background at (0,0) 176x166, flame at (176,0) 14x14, progress arrow at (176,14) 24x17,
 * energy bar fill at (176,31) 10x52.
 * <p>
 * The tier-coloured seams beside the title and the groove after "Inventory" are drawn here
 * so they fit the label widths in any language. The seams glow while the machine is working.
 */
public abstract class MachineScreen<M extends AbstractContainerMenu> extends AbstractContainerScreen<M> {
    protected static final int TEX_SIZE = 256;

    /** Seam colours per tier (see CLAUDE.md "Dark Chassis"). */
    public enum Tier {
        COAL(0xFF56381F, 0xFFFF9628, 0x60FF9628),
        ELECTRIC(0xFF1E4256, 0xFF40C4FF, 0x6040C4FF);

        final int seamOff;
        final int seamOn;
        final int seamGlow;

        Tier(int seamOff, int seamOn, int seamGlow) {
            this.seamOff = seamOff;
            this.seamOn = seamOn;
            this.seamGlow = seamGlow;
        }
    }

    private static final int TITLE_COLOR = 0xFFE4E6EC;
    private static final int LABEL_COLOR = 0xFF9EA4B0;
    private static final int GROOVE_DARK = 0xFF101114;
    private static final int GROOVE_LIGHT = 0xFF484C56;
    private static final int LABEL_GAP = 4;

    // Energy bar: inner fill area on the background, and the fill sprite on the sheet
    protected static final int ENERGY_X = 11;
    protected static final int ENERGY_Y = 17;
    protected static final int ENERGY_W = 10;
    protected static final int ENERGY_H = 52;

    protected final Identifier texture;
    private final Tier tier;

    protected MachineScreen(M menu, Inventory inventory, Component title, Identifier texture, Tier tier) {
        super(menu, inventory, title);
        this.texture = texture;
        this.tier = tier;
    }

    /** Whether the seams glow (machine burning / working). */
    protected abstract boolean isActive();

    @Override
    protected void init() {
        super.init();
        titleLabelX = (imageWidth - font.width(title)) / 2;
    }

    @Override
    public void extractBackground(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTick) {
        super.extractBackground(graphics, mouseX, mouseY, partialTick);
        graphics.blit(RenderPipelines.GUI_TEXTURED, texture, leftPos, topPos, 0, 0, imageWidth, imageHeight, TEX_SIZE, TEX_SIZE);
    }

    /** Fuel flame at (x, y) on the GUI, burning down from the top. */
    protected void drawFlame(GuiGraphicsExtractor graphics, int x, int y, float litProgress) {
        int flameHeight = Mth.ceil(litProgress * 13.0F) + 1;
        graphics.blit(RenderPipelines.GUI_TEXTURED, texture,
                leftPos + x, topPos + y + 14 - flameHeight,
                176, 14 - flameHeight,
                14, flameHeight, TEX_SIZE, TEX_SIZE);
    }

    /** Progress arrow at (x, y) on the GUI, filling left to right. */
    protected void drawArrow(GuiGraphicsExtractor graphics, int x, int y, float progress) {
        int arrowWidth = Mth.ceil(progress * 24.0F);
        if (arrowWidth > 0) {
            graphics.blit(RenderPipelines.GUI_TEXTURED, texture,
                    leftPos + x, topPos + y,
                    176, 14,
                    arrowWidth, 17, TEX_SIZE, TEX_SIZE);
        }
    }

    /** Energy bar on the left, filling from the bottom. */
    protected void drawEnergyBar(GuiGraphicsExtractor graphics, int energy, int capacity) {
        if (capacity <= 0 || energy <= 0) {
            return;
        }
        int height = Math.max(1, Math.round((float) ENERGY_H * Math.min(energy, capacity) / capacity));
        graphics.blit(RenderPipelines.GUI_TEXTURED, texture,
                leftPos + ENERGY_X, topPos + ENERGY_Y + ENERGY_H - height,
                176, 31 + ENERGY_H - height,
                ENERGY_W, height, TEX_SIZE, TEX_SIZE);
    }

    /** "12,345 / 20,000 FE" tooltip while hovering the energy bar. */
    protected void energyTooltip(GuiGraphicsExtractor graphics, int mouseX, int mouseY, int energy, int capacity) {
        if (isHovering(ENERGY_X, ENERGY_Y, ENERGY_W, ENERGY_H, mouseX, mouseY)) {
            graphics.setTooltipForNextFrame(Component.translatable("gui.comminutioncraft.energy",
                    formatFe(energy), formatFe(capacity)), mouseX, mouseY);
        }
    }

    protected static String formatFe(int amount) {
        return String.format(Locale.ROOT, "%,d", amount);
    }

    @Override
    protected void extractLabels(GuiGraphicsExtractor graphics, int mouseX, int mouseY) {
        // Seams either side of the title: ──── Coal Granulator ────
        int seamY = titleLabelY + 3;
        int titleEnd = titleLabelX + font.width(title);
        seam(graphics, 8, titleLabelX - LABEL_GAP, seamY);
        seam(graphics, titleEnd + LABEL_GAP, imageWidth - 8, seamY);
        graphics.text(font, title, titleLabelX, titleLabelY, TITLE_COLOR, false);

        // Engraved groove after the inventory label, separating machine and player inventory
        int grooveX = inventoryLabelX + font.width(playerInventoryTitle) + LABEL_GAP;
        int grooveY = inventoryLabelY + 3;
        graphics.fill(grooveX, grooveY, imageWidth - 8, grooveY + 1, GROOVE_DARK);
        graphics.fill(grooveX, grooveY + 1, imageWidth - 8, grooveY + 2, GROOVE_LIGHT);
        graphics.text(font, playerInventoryTitle, inventoryLabelX, inventoryLabelY, LABEL_COLOR, false);
    }

    private void seam(GuiGraphicsExtractor graphics, int x0, int x1, int y) {
        if (x1 <= x0) {
            return;
        }
        if (isActive()) {
            graphics.fill(x0, y - 1, x1, y, tier.seamGlow);
            graphics.fill(x0, y, x1, y + 1, tier.seamOn);
            graphics.fill(x0, y + 1, x1, y + 2, tier.seamGlow);
        } else {
            graphics.fill(x0, y, x1, y + 1, tier.seamOff);
        }
    }
}
